public static String mapEmptyToToml(Fleetwood.MapEmpty msg) throws ProtoException {
if (msg == null) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT, "MapEmpty is null");
}
try {
String json = mapEmptyToJson(msg);
Gson gson = new Gson();
Map<String, Object> map = gson.fromJson(json, new com.google.gson.reflect.TypeToken<Map<String, Object>>(){}.getType());
StringBuilder toml = new StringBuilder();
if (map == null || map.isEmpty()) {
return "# Empty MapEmpty\n";
}
for (Map.Entry<String, Object> entry : map.entrySet()) {
toml.append(entry.getKey()).append(" = ");
if (entry.getValue() instanceof String) {
toml.append("\"").append(entry.getValue()).append("\"");
} else {
toml.append(entry.getValue());
}
toml.append("\n");
}
return toml.toString();
} catch (ProtoException e) {
throw e;
} catch (Exception e) {
throw new ProtoException(ProtoException.INTERNAL, "Failed to serialize MapEmpty to TOML: " + e.getMessage(), e);
}
}
public static Fleetwood.MapEmpty mapEmptyFromToml(String tomlStr) throws ProtoException {
if (tomlStr == null || tomlStr.isEmpty()) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT, "tomlStr is null or empty");
}
try {
Toml toml = new Toml().read(tomlStr);
Map<String, Object> map = toml.toMap();
Gson gson = new Gson();
String json = gson.toJson(map);
return mapEmptyFromJson(json);
} catch (ProtoException e) {
throw e;
} catch (Exception e) {
throw new ProtoException(ProtoException.INTERNAL, "Failed to parse MapEmpty from TOML: " + e.getMessage(), e);
}
}
// ============ Validation ============
public static void validateConfig(Fleetwood.Config msg) throws ProtoException {
if (msg == null) {
return;
}
// Validate sessionTimeoutSeconds (assert_duration: POSITIVE)
if (msg.getSessionTimeoutSeconds() <= 0) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field sessionTimeoutSeconds must be positive (> 0), got: %d", msg.getSessionTimeoutSeconds()));
}
// Validate sessionTimeoutSeconds (assert_duration_min: 30)
if (msg.getSessionTimeoutSeconds() < 30L) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field sessionTimeoutSeconds must be >= 30, got: %d", msg.getSessionTimeoutSeconds()));
}
// Validate sessionTimeoutSeconds (assert_duration_max: 600)
if (msg.getSessionTimeoutSeconds() > 600L) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field sessionTimeoutSeconds must be <= 600, got: %d", msg.getSessionTimeoutSeconds()));
}
// Validate refreshTokenLifetimeSeconds (assert_duration: POSITIVE)
if (msg.getRefreshTokenLifetimeSeconds() <= 0) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field refreshTokenLifetimeSeconds must be positive (> 0), got: %d", msg.getRefreshTokenLifetimeSeconds()));
}
// Validate refreshTokenLifetimeSeconds (assert_duration_min: 3600)
if (msg.getRefreshTokenLifetimeSeconds() < 3600L) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field refreshTokenLifetimeSeconds must be >= 3600, got: %d", msg.getRefreshTokenLifetimeSeconds()));
}
// Validate refreshTokenLifetimeSeconds (assert_duration_max: 2592000)
if (msg.getRefreshTokenLifetimeSeconds() > 2592000L) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field refreshTokenLifetimeSeconds must be <= 2592000, got: %d", msg.getRefreshTokenLifetimeSeconds()));
}
// Validate autoRefreshBeforeSeconds (assert_duration: POSITIVE)
if (msg.getAutoRefreshBeforeSeconds() <= 0) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field autoRefreshBeforeSeconds must be positive (> 0), got: %d", msg.getAutoRefreshBeforeSeconds()));
}
// Validate autoRefreshBeforeSeconds (assert_duration_min: 60)
if (msg.getAutoRefreshBeforeSeconds() < 60L) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field autoRefreshBeforeSeconds must be >= 60, got: %d", msg.getAutoRefreshBeforeSeconds()));
}
// Validate autoRefreshBeforeSeconds (assert_duration_max: 86400)
if (msg.getAutoRefreshBeforeSeconds() > 86400L) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field autoRefreshBeforeSeconds must be <= 86400, got: %d", msg.getAutoRefreshBeforeSeconds()));
}
}
