public static void validateInstallTokenRequest(Fleetwood.InstallTokenRequest msg) throws ProtoException {
if (msg == null) {
return;
}
// Validate sessionId (assert_required)
if (msg.getSessionId().isEmpty()) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,"field sessionId is required");
}
// Validate sessionId (assert_min_length: 64)
if (msg.getSessionId().length() < 64) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field sessionId must be at least 64 characters, got: %d", msg.getSessionId().length()));
}
// Validate sessionId (assert_max_length: 128)
if (msg.getSessionId().length() > 128) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field sessionId must be at most 128 characters, got: %d", msg.getSessionId().length()));
}
// Validate token (assert_required)
if (msg.getToken().isEmpty()) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,"field token is required");
}
// Validate token (assert_min_length: 1)
if (msg.getToken().length() < 1) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field token must be at least 1 characters, got: %d", msg.getToken().length()));
}
// Validate token (assert_max_length: 8192)
if (msg.getToken().length() > 8192) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field token must be at most 8192 characters, got: %d", msg.getToken().length()));
}
}
