// ============ Merge ============
public static Fleetwood.Config.Builder mergeConfig(Fleetwood.Config dst, Fleetwood.Config src) {
Fleetwood.Config.Builder builder = dst.toBuilder();
if (dst.getSessionTimeoutSeconds() == 0) { builder.setSessionTimeoutSeconds(src.getSessionTimeoutSeconds()); }
if (dst.getRefreshTokenLifetimeSeconds() == 0) { builder.setRefreshTokenLifetimeSeconds(src.getRefreshTokenLifetimeSeconds()); }
if (dst.getAutoRefreshBeforeSeconds() == 0) { builder.setAutoRefreshBeforeSeconds(src.getAutoRefreshBeforeSeconds()); }
return builder;
}
public static Fleetwood.SessionRequest.Builder mergeSessionRequest(Fleetwood.SessionRequest dst, Fleetwood.SessionRequest src) {
Fleetwood.SessionRequest.Builder builder = dst.toBuilder();
if (dst.getMsgCase() == Fleetwood.SessionRequest.MsgCase.MSG_NOT_SET) {
switch (src.getMsgCase()) {
case SESSION_ID: builder.setSessionId(src.getSessionId()); break;
default: break;
}
}
return builder;
}
public static Fleetwood.SessionResponse.Builder mergeSessionResponse(Fleetwood.SessionResponse dst, Fleetwood.SessionResponse src) {
Fleetwood.SessionResponse.Builder builder = dst.toBuilder();
if (dst.getMsgCase() == Fleetwood.SessionResponse.MsgCase.MSG_NOT_SET) {
switch (src.getMsgCase()) {
case TOKEN: builder.setToken(src.getToken()); break;
case ERROR: builder.setError(src.getError()); break;
default: break;
}
}
return builder;
}
public static Fleetwood.InstallTokenRequest.Builder mergeInstallTokenRequest(Fleetwood.InstallTokenRequest dst, Fleetwood.InstallTokenRequest src) {
Fleetwood.InstallTokenRequest.Builder builder = dst.toBuilder();
if (dst.getSessionId().isEmpty()) { builder.setSessionId(src.getSessionId()); }
if (dst.getToken().isEmpty()) { builder.setToken(src.getToken()); }
return builder;
}
public static Fleetwood.FleetwoodConfigState.Builder mergeFleetwoodConfigState(Fleetwood.FleetwoodConfigState dst, Fleetwood.FleetwoodConfigState src) {
Fleetwood.FleetwoodConfigState.Builder builder = dst.toBuilder();
if (!dst.hasConfig() && src.hasConfig()) { builder.setConfig(src.getConfig()); }
else if (dst.hasConfig() && src.hasConfig()) { builder.setConfig(mergeConfig(dst.getConfig(), src.getConfig()).build()); }
return builder;
}
