public static Map<String, String> configToEnvVar(Fleetwood.Config msg) {
Map<String, String> result = new HashMap<>();
result.put("PROTO_CONFIG_SESSION_TIMEOUT_SECONDS", String.valueOf(msg.getSessionTimeoutSeconds()));
result.put("PROTO_CONFIG_REFRESH_TOKEN_LIFETIME_SECONDS", String.valueOf(msg.getRefreshTokenLifetimeSeconds()));
result.put("PROTO_CONFIG_AUTO_REFRESH_BEFORE_SECONDS", String.valueOf(msg.getAutoRefreshBeforeSeconds()));
return result;
}
public static Fleetwood.Config.Builder configFromEnvVar(Map<String, String> env) {
Fleetwood.Config.Builder builder = Fleetwood.Config.newBuilder();
String val;
val = env.get("PROTO_CONFIG_SESSION_TIMEOUT_SECONDS");
if (val != null && !val.isEmpty()) {
builder.setSessionTimeoutSeconds(Long.parseLong(val));
}
val = env.get("PROTO_CONFIG_REFRESH_TOKEN_LIFETIME_SECONDS");
if (val != null && !val.isEmpty()) {
builder.setRefreshTokenLifetimeSeconds(Long.parseLong(val));
}
val = env.get("PROTO_CONFIG_AUTO_REFRESH_BEFORE_SECONDS");
if (val != null && !val.isEmpty()) {
builder.setAutoRefreshBeforeSeconds(Long.parseLong(val));
}
return builder;
}
